 const {t,language}=usePreferences();const qc=useQueryClient();const [params,setParams]=useSearchParams();const location=useLocation();const personal=profile.role==='salesperson';const pageName=personal?'requests':financePage(location.pathname);const dashboard=pageName==='dashboard';const view=['dashboard','disbursements','accounts'].includes(pageName)?'requests':pageName==='invoices'?'sales_invoices':pageName;const [notice,setNotice]=useState('');const [page,setPage]=useState(1);const [auditSearch,setAuditSearch]=useState('');const [auditActivity,setAuditActivity]=useState('');const [auditStatus,setAuditStatus]=useState('');const today=nairobiDate();const [filters,setFilters]=useState<FinanceFilters>({from:params.get('from')??(/^\d{4}-\d{2}$/.test(params.get('month')??'')?`${params.get('month')}-01`:`${today.slice(0,4)}-01-01`),to:params.get('to')??(/^\d{4}-\d{2}$/.test(params.get('month')??'')?nairobiDate(new Date(Date.UTC(Number(params.get('month')!.slice(0,4)),Number(params.get('month')!.slice(5,7)),0))):`${today.slice(0,4)}-12-31`),status:params.get('status')??(pageName==='disbursements'?'awaiting_payment':''),owner:profile.role!=='salesperson'&&/^\d+$/.test(params.get('staff')??'')?params.get('staff')!:''});const [action,setAction]=useState<Action|null>(null);const [error,setError]=useState<unknown>();const [exporting,setExporting]=useState(false);const [docOrder,setDocOrder]=useState<number|null>(null);const [letterhead,setLetterhead]=useState(false);
