 {false&&<><p>{r.description} · {formatMoney(r.amount,language)} · {t(r.kind)}</p><Field label="decision"><select value={values.decision} onChange={e=>change('decision',e.target.value)}><option value="approved">{t('accepted')}</option><option value="returned">{t('returned')}</option></select></Field>{values.decision==='returned'&&note('reason')}{values.decision==='approved'&&r.kind==='refund'&&checkbox()}</>}

 {k==='account'&&<>{input('name')}<Field label="method"><select value={values.method} onChange={e=>change('method',e.target.value)}>{['Cash','Bank','M-Pesa','Other'].map(s=><option key={s}>{s}</option>)}</select></Field></>}
