 {k==='supplierPayee'&&<><Field label="supplierName"><input required maxLength={200} value={values.name??''} onChange={e=>change('name',e.target.value)}/></Field><Field label="contactPerson"><input required maxLength={200} value={values.contact_person??''} onChange={e=>change('contact_person',e.target.value)}/></Field><div className="form-grid"><Field label="phone"><input type="tel" maxLength={80} value={values.phone??''} onChange={e=>change('phone',e.target.value)}/></Field><Field label="email"><input type="email" maxLength={254} value={values.email??''} onChange={e=>change('email',e.target.value)}/></Field></div>{input('address','text',false)}</>}
 {k==='statement'&&<>{select('account_id',meta.refund_accounts,'paymentAccount')}{input('reference')}<Field label="direction"><select value={values.direction} onChange={e=>change('direction',e.target.value)}><option value="in">{t('in')}</option><option value="out">{t('out')}</option></select></Field>{money()}{input('date','date')}</>}
 {k==='contraTransfer'&&<><p className="notice">{t('contraTransferFormHint')}</p>{select('source_account_id',meta.refund_accounts,'contraSourceAccount')}{select('destination_account_id',meta.refund_accounts,'contraDestinationAccount')}{money()}{input('date','date')}{input('reference')}{note('description')}</>}
