 {k==='batchCost'&&<><Field label="batch_id"><select required value={values.batch_id??''} onChange={e=>{const id=e.target.value;const used=ops.batch_used.filter((x:Row)=>String(x.batch_id)===id);const standard=ops.batch_standard.filter((x:Row)=>String(x.batch_id)===id);setValues(prev=>({...prev,batch_id:id,...Object.fromEntries(used.map((x:Row)=>['actual_'+x.material_id,String(x.quantity)])),...Object.fromEntries(standard.map((x:Row)=>['std_'+x.material_id,String(x.quantity)]))}));}}><option value="">{t('choose')}</option>{ops.production_batches.map((b:Row)=><option key={b.id} value={b.id}>{b.lot_number} · {b.product_name}</option>)}</select></Field><p>{t('standardActualMaterialCosts')}</p>{ops.production_materials.map((m:Row)=><div className="finance-cost-line" key={m.id}><strong>{m.name} · {m.base_unit}</strong><Field label="standard_quantity"><input type="number" min="0" step="0.001" value={values['std_'+m.id]??''} onChange={e=>change('std_'+m.id,e.target.value)}/></Field><Field label="actual_quantity"><input type="number" min="0" step="0.001" value={values['actual_'+m.id]??''} onChange={e=>change('actual_'+m.id,e.target.value)}/></Field><Field label="unit_cost"><input type="number" min="0" step="0.01" value={values['cost_'+m.id]??''} onChange={e=>change('cost_'+m.id,e.target.value)}/></Field></div>)}<h3>{t('packagingCostBreakdown')}</h3>{['primary_packaging','secondary_packaging'].map(type=><div key={type} className="finance-cost-line"><strong>{t(type)}</strong>{Array.from({length:3},(_,i)=><div className="form-grid" key={i}><TextInput label="description" type="text" value={values[type+'_name_'+i]??''} onChange={v=>change(type+'_name_'+i,v)}/><TextInput label="unit_cost" value={values[type+'_cost_'+i]??''} onChange={v=>change(type+'_cost_'+i,v)}/></div>)}</div>)}<div className="form-grid">{['utilities','labor','tank_hours','tank_rate','fill_hours','fill_rate','waste','recovery'].map(x=><TextInput key={x} label={x} value={values[x]??''} onChange={v=>change(x,v)}/>)}</div>{note('notes')}</>}
 {k==='purchaseOrder'&&<><Field label="supplier_id"><select required value={values.supplier_id??''} onChange={e=>change('supplier_id',e.target.value)}><option value="">{t('choose')}</option>{meta.payees.filter((p:Row)=>!p.staff_id).map((p:Row)=><option key={p.id} value={p.id}>{p.name}</option>)}</select></Field>{input('po_number')}{input('currency')}{ops.production_materials.map((m:Row)=><div className="finance-cost-line" key={m.id}><strong>{m.name} · {m.purchase_unit}</strong><TextInput label="quantity" value={values['qty_'+m.id]??''} onChange={v=>change('qty_'+m.id,v)}/><TextInput label="unit_price" value={values['price_'+m.id]??''} onChange={v=>change('price_'+m.id,v)}/></div>)}</>}
