 {k==='supplierInvoice'&&<><Field label="po_id"><select required value={values.po_id??''} onChange={e=>change('po_id',e.target.value)}><option value="">{t('choose')}</option>{ops.received_pos.map((x:Row)=><option key={x.id} value={x.id}>{x.po_number}</option>)}</select></Field><Field label="grn_id"><select required value={values.grn_id??''} onChange={e=>change('grn_id',e.target.value)}><option value="">{t('choose')}</option>{ops.approved_grns.map((x:Row)=><option key={x.id} value={x.id}>{x.grn_number}</option>)}</select></Field>{input('invoice_number')}{input('currency')}{input('subtotal','number')}{input('tax_amount','number',false)}{input('duty_amount','number',false)}{input('document_path',undefined,false)}</>}
