 {k==='etims'&&<><Field label="invoice_id"><select required value={values.invoice_id??''} onChange={e=>change('invoice_id',e.target.value)}><option value="">{t('choose')}</option>{ops.sales_invoices.map((x:Row)=><option key={x.id} value={x.id}>{x.invoice_number}</option>)}</select></Field><Field label="etims_status"><select value={values.etims_status??'queued'} onChange={e=>change('etims_status',e.target.value)}>{['queued','submitted','accepted','rejected','unavailable'].map(s=><option key={s} value={s}>{t(s)}</option>)}</select></Field>{input('etims_control',undefined,false)}{input('etims_response',undefined,false)}</>}
 {['operatingEntry','operatingExpenseEntry'].includes(k)&&<>{k==='operatingExpenseEntry'?<p className="notice">{t('operatingExpenseEntryHint')}</p>:<Field label="direction"><select value={values.direction} onChange={e=>change('direction',e.target.value)}><option value="revenue">{t('revenue')}</option><option value="expense">{t('expense')}</option></select></Field>}<Field label="category"><select required value={k==='operatingExpenseEntry'?values.expenseClass:values.category??'operational'} onChange={e=>change(k==='operatingExpenseEntry'?'expenseClass':'category',e.target.value)}>{(k==='operatingExpenseEntry'?['operational','financial']:['operational','financial','other','sales','tax','duty']).map(s=><option key={s} value={s}>{t(s)}</option>)}</select></Field>{k==='operatingExpenseEntry'&&<><Field label="expenseSubcategory"><select required value={values.subcategory} onChange={e=>change('subcategory',e.target.value)}><option value="">{t('choose')}</option>{(values.expenseClass==='operational'?['Rent','Utilities','Transport','Travel','Repairs and maintenance','Communication','Office supplies','Marketing','Insurance','Other']:['Bank charges','Interest expense','Loan fees','Foreign exchange loss','Other']).map(s=><option key={s} value={s}>{s}</option>)}</select></Field></>}{money()}{input('date','date')}{note('description')}{input('reference')}{select('account_id',meta.refund_accounts,k==='operatingExpenseEntry'?'expensePaidFrom':'paymentAccount')}</>}

